<section class="erp-card"><h2>مغایرت‌گیری بانکی</h2><p>ماندهٔ دفتر و اقلام تطبیق‌شده از اسناد تأییدشده/قطعی بازحساب می‌شوند. اختلاف صفر یعنی اقلام انتخاب‌شده با ماندهٔ صورتحساب برابرند؛ ثبت این صفحه اسناد دفتر را قطعی نمی‌کند.</p>
<form method="get" action="<?php echo esc_url(agah_erp_url()); ?>" class="erp-filter"><input type="hidden" name="page_id" value="<?php echo (int)get_option('agah_erp_page_id'); ?>"><input type="hidden" name="c" value="<?php echo (int)$cid; ?>"><input type="hidden" name="p" value="bank_reconciliation"><label>بانک<select name="account_id"><option value="0">انتخاب</option><?php foreach($accounts as $a): ?><option value="<?php echo (int)$a['id']; ?>" <?php selected($account,$a['id']); ?>><?php echo esc_html($a['name']); ?></option><?php endforeach; ?></select></label><label>تا تاریخ شمسی<input name="as_of" value="<?php echo esc_attr(Jalali::format($date,false)); ?>" data-jalali dir="ltr"></label><button type="submit" class="btn btn-outline">نمایش دفتر بانک</button></form>
<?php if($account): $ledger=TreasuryService::ledger($cid,$account,$date,Request::int('get','pg',1));if($ledger['account']['kind']!=='bank')throw new \Agah\Erp\Core\ValidationException(['account'=>'حساب بانکی انتخاب کنید.']);$matched=$rec['matched']??[]; ?>
<p>ماندهٔ دفتر: <?php echo esc_html(Money::fmt($ledger['balance'],Ctx::unit())); ?> <?php if($rec): ?> | اقلام تطبیق‌نشده: <?php echo esc_html(Money::fmt($rec['unmatched'],Ctx::unit())); ?> | اختلاف: <strong class="<?php echo $rec['difference']===0?'erp-ok':'erp-err'; ?>"><?php echo esc_html(Money::fmt($rec['difference'],Ctx::unit())); ?></strong><?php endif; ?></p>
<?php if(Ctx::can('treasury_account.edit')): ?><form method="post" class="erp-form"><?php self::form('module_bank_reconcile',$cid,'bank_reconciliation',$id); ?><input type="hidden" name="revision" value="<?php echo (int)($record['revision']??0); ?>"><input type="hidden" name="treasury_account_id" value="<?php echo (int)$account; ?>"><input type="hidden" name="as_of_date" value="<?php echo esc_attr(Jalali::format($date,false)); ?>"><?php self::input('statement_balance','ماندهٔ صورتحساب بانک (بدهکار مثبت)',Money::toInputValue((int)($record['statement_balance']??0),Ctx::unit()),'text','required inputmode="decimal"');self::input('notes','یادداشت',$record['notes']??'','text','maxlength="500"');
$visible=array_map('intval',array_column($ledger['rows'],'id'));foreach(array_diff($matched,$visible) as $hidden): ?><input type="hidden" name="matched[]" value="<?php echo (int)$hidden; ?>"><?php endforeach; ?>
<?php endif; ?>
<div class="erp-scroll"><table class="erp-table"><thead><tr><th>تطبیق</th><th>تاریخ/سند</th><th>شرح</th><th>بدهکار</th><th>بستانکار</th></tr></thead><tbody><?php foreach($ledger['rows'] as $l): ?><tr><td><?php if(Ctx::can('treasury_account.edit')): ?><input type="checkbox" name="matched[]" value="<?php echo (int)$l['id']; ?>" aria-label="تطبیق ردیف <?php echo (int)$l['id']; ?>" <?php checked(in_array((int)$l['id'],$matched,true)); ?>><?php else: echo in_array((int)$l['id'],$matched,true)?'✓':'—';endif; ?></td><td><?php echo esc_html(Jalali::format($l['voucher_date']).' #'.Money::toFa($l['number'])); ?></td><td><?php echo esc_html($l['description']); ?></td><td><?php echo esc_html(Money::fmt((int)$l['debit'],Ctx::unit())); ?></td><td><?php echo esc_html(Money::fmt((int)$l['credit'],Ctx::unit())); ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(Ctx::can('treasury_account.edit')): ?><button type="submit" class="btn btn-primary">ذخیرهٔ تطبیق</button></form><?php endif;self::pages($ledger['pages'],$ledger['page']);endif; ?>
<h3>مغایرت‌گیری‌های ثبت‌شده</h3><?php foreach(Db::rows('SELECT r.id,r.as_of_date,a.name FROM '.Db::t('bank_reconciliations').' r JOIN '.Db::t('treasury_accounts').' a ON a.company_id=r.company_id AND a.id=r.treasury_account_id WHERE r.company_id=%d ORDER BY r.id DESC LIMIT 50',$cid) as $r): ?><p><a href="<?php echo esc_url(agah_erp_url(['c'=>$cid,'p'=>'bank_reconciliation','id'=>$r['id']])); ?>"><?php echo esc_html($r['name'].' / '.Jalali::format($r['as_of_date'])); ?></a></p><?php endforeach; ?></section>
